sub_1E01:                               ; CODE XREF: sub_0+1E8↑j
                                        ; ROM:01FA↑j ...
                ld      a, (byte_1A3B)
                cp      #0
                jr      Z, loc_1E1B
                call    get_emulation_routine
                ld      (set_emulated_videomode), hl ; routine to setup current emulated video mode
                ld      (emulate_current_videomode), de ; routine to render current emulated video mode
                ld      a, #0
                ld      (byte_1A3B), a
                ld      hl, (set_emulated_videomode) ; routine to setup current emulated video mode
                jp      (hl)
; ---------------------------------------------------------------------------

loc_1E1B:                               ; CODE XREF: sub_1E01+5↑j
                ld      a, (byte_1E32)
                cp      #0
                jr      Z, loc_1E2C
                ld      a, #0xA5
                out0    (0xA0), a
                ld      a, #0
                ld      (byte_1E32), a

loc_1E2C:                               ; CODE XREF: sub_1E01+1F↑j
                ld      hl, (emulate_current_videomode) ; routine to render current emulated video mode
                jp      (hl)
; End of function sub_1E01

; ---------------------------------------------------------------------------
                jp      (hl)
; ---------------------------------------------------------------------------
vga_mode:       .db 0                   ; DATA XREF: set_mode+9↑w
                                        ; get_status+B↑r ...
                                        ; 01 = 40x25, 03 = 80x25, 53 = 640x480x256, 13 = 320x200x256, 61 = 640x400x256, FA = 560x192x16, FB=280x192x16, FC=40x24, FD=80x24, FE=640x200
byte_1E32:      .db 0                   ; DATA XREF: set_mode+11↑w
                                        ; sub_1E01:loc_1E1B↑r ...
; ---------------------------------------------------------------------------

loc_1E33:                               ; DATA XREF: get_emulation_routine+7↓o
                ld      a, (vga_mode)   ; 01 = 40x25, 03 = 80x25, 53 = 640x480x256, 13 = 320x200x256, 61 = 640x400x256, FA = 560x192x16, FB=280x192x16, FC=40x24, FD=80x24, FE=640x200
                call    set_video_mode  ; A = video mode (13 = 320x200x256, 53 = 640x480x256, etc)
                jr      C, loc_1E4B
                call    screen_on
                ld      a, #0xA5
                out0    (0xA0), a
                ld      a, #0
                ld      (byte_1E32), a
