get_emulation_routine:                  ; CODE XREF: sub_1E01+7↑p
                ld      a, (emul_flag)  ; 00 = emulating Apple II video modes, 01 = disable emulation
                cp      #0
                jr      Z, emulate_superhires_check
                ld      hl, #loc_1E33
                ld      de, #emulation_disabled
                ret
; ---------------------------------------------------------------------------

emulate_superhires_check:               ; CODE XREF: get_emulation_routine+5↑j
                ld      a, (shr_enabled_flag) ; Enable Super Hires softswitch (bit 7 of NEWVIDEO softswitch). 1=Enabled.
                cp      #0
                jr      Z, emulate_text80_check
                ld      hl, #set_videomode_superhires
                ld      de, #emulate_superhires
                ret
; ---------------------------------------------------------------------------

