                jr      Z, emulate_hires_dhr_check
                ld      a, (text80_enabled_flag) ; SET80VID ($C00D) softswitch. 1=Enabled.
                cp      #0
                jr      Z, emulate_text40_check
                ld      hl, #set_videomode_text80
                ld      de, #emulate_text80
                ret
