                ld      a, (hires_flag) ; HIRES ($C057) softswitch. 0=Lores, 1=Hires.
                cp      #0
                jr      Z, emulate_lores_dlr_check
                ld      a, (doublewidth_flag) ; $C05F softswitch. 1=Double width graphics. 0=Single width graphics.
                cp      #0
                jr      Z, emulate_single_hires
                ld      a, (text80_enabled_flag) ; SET80VID ($C00D) softswitch. 1=Enabled.
                cp      #0
                jr      Z, emulate_single_hires
                ld      hl, #set_videomode_double_hires
                ld      de, #emulate_double_hires
                ret
