; =============== S U B R O U T I N E =======================================


set_videomode_hires:                    ; DATA XREF: get_emulation_routine:emulate_single_hires↑o
                di
                ld      a, #0x94        ; 09/4000
                out0    (0x38), a       ; MMU Common Base Register (CBR)
                ld      a, #0xC2        ; 0000-1FFF = Common Area 0
                                        ; 2000-BFFF = Bank Area
                                        ; C000-FFFF = Common Area 1
                out0    (0x3A), a       ; MMU Common/Bank Area Register (CBAR)
                call    access_softswitch1 ; Access the softswitch at 5/0000
                ld      a, #0xFB        ; 280x192x16
                call    set_video_mode  ; A = video mode (13 = 320x200x256, 53 = 640x480x256, etc)
                ld      a, #1
                ld      bc, #0x3C4      ; Select Sequencer clocking mode
                out     (c), a
                ld      bc, #0x3C5
                in      a, (c)
                res     5, a            ; Turn screen off
                ld      d, a
                ld      a, #1
                ld      bc, #0x3C4      ; Select Sequencer clocking mode
                out     (c), a
                ld      a, d
                ld      bc, #0x3C5
                out     (c), a
                call    setup_hires_palette
                ld      a, #0x24 ; '$'  ; Oak extended write segment register
                ld      bc, #0x3DE
                out     (c), a
                ld      a, #1
                ld      bc, #0x3DF
                out     (c), a
                ld      a, #2
                ld      bc, #0x3C4      ; Select Sequencer map mask
                out     (c), a
                ld      a, #1           ; Write to plane 0
                ld      bc, #0x3C5
                out     (c), a
                ld      bc, #0x100
                ld      hl, #hires_B200
                ld      de, #0xC000     ; Copy $B200-$B2FF to A/0000 (plane 1)
                ldir
                ld      a, #2           ; Select Sequencer map mask
                ld      bc, #0x3C4
                out     (c), a
                ld      a, #2           ; Write to plane 2
                ld      bc, #0x3C5
                out     (c), a
                ld      bc, #0x100
                ld      de, #0xC000     ; Copy $B300-$B3FF -> A/0000 (plane 2)
                ldir
                ld      a, #2           ; Select Sequencer map mask
                ld      bc, #0x3C4
                out     (c), a
                ld      a, #4           ; Write to plane 3
                ld      bc, #0x3C5
                out     (c), a
                ld      bc, #0x100
                ld      de, #0xC000     ; Copy $B400-$B4FF -> A/0000 (plane 3)
                ldir
                ld      a, #2           ; Select Sequencer map mask
                ld      bc, #0x3C4
                out     (c), a
                ld      a, #8           ; Write to plane 4
                ld      bc, #0x3C5
                out     (c), a
                ld      bc, #0x100
                ld      de, #0xC000     ; Copy $B500-$B5FF -> A/0000 (plane 4)
                ldir
                ld      a, #2           ; Select Sequencer map mask
                ld      bc, #0x3C4
                out     (c), a
                ld      a, #1           ; Write to plane 1
                ld      bc, #0x3C5
                out     (c), a
                ld      bc, #0x100
                ld      hl, #hires_B600
                ld      de, #0xC100     ; Copy $B600-$B6FF -> A/0100 (plane 1)
                ldir
                ld      a, #2           ; Select Sequencer map mask
                ld      bc, #0x3C4
                out     (c), a
                ld      a, #2           ; Write to plane 2
                ld      bc, #0x3C5
                out     (c), a
                ld      bc, #0x100
                ld      de, #0xC100     ; Copy $B700-$B7FF -> A/0100 (plane 2)
                ldir
                ld      a, #2           ; Select Sequencer map mask
                ld      bc, #0x3C4
                out     (c), a
                ld      a, #4           ; Write to plane 3
                ld      bc, #0x3C5
                out     (c), a
                ld      bc, #0x100
                ld      de, #0xC100     ; Copy $B800-$B8FF -> A/0100 (plane 3)
                ldir
                ld      a, #2           ; Select Sequencer map mask
                ld      bc, #0x3C4
                out     (c), a
                ld      a, #8           ; Write to plane 4
                ld      bc, #0x3C5
                out     (c), a
                ld      bc, #0x100
                ld      de, #0xC100     ; Copy $B900-$B9FF -> A/0100 (plane 4)
                ldir
                ld      a, #2           ; Select Sequencer map mask
                ld      bc, #0x3C4
                out     (c), a
                ld      a, #0xF         ; Write to all planes
                ld      bc, #0x3C5
                out     (c), a
                ld      a, #0x23 ; '#'  ; Oak extended read segment register
                ld      bc, #0x3DE
                out     (c), a
                ld      a, #1
                ld      bc, #0x3DF
                out     (c), a
                ld      a, #0x24 ; '$'  ; Oak extended write segment register
                ld      bc, #0x3DE
                out     (c), a
                ld      a, #0
                ld      bc, #0x3DF
                out     (c), a
                ei
                jp      sub_1E01
; End of function set_videomode_hires


; =============== S U B R O U T I N E =======================================


emulate_hires:                          ; DATA XREF: get_emulation_routine+57↑o
                ld      a, #5
                ld      bc, #0x3CE      ; select graphics controller mode register
                out     (c), a
                ld      a, #1
                ld      bc, #0x3CF
                out     (c), a          ; select write mode 1
                call    render_hires
                call    render_hires
                call    render_hires
                call    render_hires
                call    render_hires
                call    render_hires
                call    render_hires
                call    render_hires
                ld      a, #5
                ld      bc, #0x3CE
                out     (c), a
                ld      a, #0
                ld      bc, #0x3CF
                out     (c), a
                jp      sub_1E01
; End of function emulate_hires


