render_hires_line:                      ; CODE XREF: render_16_hires_lines_in_page1+1↑p
                                        ; render_16_hires_lines_in_page2+1↑p
                ld      bc, #0x27 ; '''
                add     ix, bc
                push    ix
                inc     ix
                add     hl, bc
                push    hl
                ld      c, #4
                exx
                pop     bc
                pop     de
                exx

render_hires_line_loop:                 ; CODE XREF: render_hires_line+50↓j
                exx
                ld      a, (bc)         ; read byte from hires screen area (2000-3FFF or 4000-5FFF)
                ld      l, a            ; use C100-C1FF as a lookup table for even bytes
                ld      h, #0xC1
                ldd                     ; write remapped byte to C000-DDFF
                ld      a, (bc)
                ld      l, a
                ld      h, #0xC0        ; use C000-C0FF as a lookup table for odd bytes
                ldd
                ld      a, (bc)
                ld      l, a
                ld      h, #0xC1
                ldd
                ld      a, (bc)
                ld      l, a
                ld      h, #0xC0
                ldd
                ld      a, (bc)
                ld      l, a
                ld      h, #0xC1
                ldd
                ld      a, (bc)
                ld      l, a
                ld      h, #0xC0
                ldd
                ld      a, (bc)
                ld      l, a
                ld      h, #0xC1
                ldd
                ld      a, (bc)
                ld      l, a
                ld      h, #0xC0
                ldd
                ld      a, (bc)
                ld      l, a
                ld      h, #0xC1
                ldd
                ld      a, (bc)
                ld      l, a
                ld      h, #0xC0
                ldd
                exx
                dec     c
                jr      NZ, render_hires_line_loop
                ret
; End of function render_hires_line


