render_text_line_in_8x8_font:           ; CODE XREF: render_hires+AA↑p
                                        ; render_hires+B3↑p ...
                ld      b, (hl)
                ld      a, #5
                ld      bc, #0x3CE
                out     (c), a
                ld      a, #0
                ld      bc, #0x3CF
                out     (c), a
                ld      c, #0x28 ; '('

render_text_line_loop:                  ; CODE XREF: render_text_line_in_8x8_font+50↓j
                push    de
                ld      a, (hl)
                exx
                ld      b, a
                call    get_text_colour ; Returns H = foreground colour, L = background colour
                exx
                ld      a, (hl)
                exx
                ld      hl, (word_1A3C)
                ld      l, a
                ld      b, (hl)
                ld      c, #8
                mlt     bc
                ld      hl, #font_table_8x8 ; MouseText 0 - Closed Apple
                add     hl, bc
                push    hl
                pop     bc
                ld      de, #0x28 ; '('
                pop     hl
                ld      a, (bc)
                ld      (hl), a
                add     hl, de
                inc     bc
                ld      a, (bc)
                ld      (hl), a
                add     hl, de
                inc     bc
                ld      a, (bc)
                ld      (hl), a
                add     hl, de
                inc     bc
                ld      a, (bc)
                ld      (hl), a
                add     hl, de
                inc     bc
                ld      a, (bc)
                ld      (hl), a
                add     hl, de
                inc     bc
                ld      a, (bc)
                ld      (hl), a
                add     hl, de
                inc     bc
                ld      a, (bc)
                ld      (hl), a
                add     hl, de
                inc     bc
                ld      a, (bc)
                ld      (hl), a
                exx
                inc     de
                inc     hl
                dec     c
                jp      NZ, render_text_line_loop
                ld      a, #5
                ld      bc, #0x3CE
                out     (c), a
                ld      a, #1
                ld      bc, #0x3CF
                out     (c), a
                ret
; End of function render_text_line_in_8x8_font

