                jp      Z, copy_font_applecolor_rgb
                ld      a, #2
                ld      bc, #0x3C4
                out     (c), a
                ld      a, #4
                ld      bc, #0x3C5
                out     (c), a
                ld      a, #4
                ld      bc, #0x3C4
                out     (c), a
                ld      a, #6
