set_videomode_double_hires:             ; DATA XREF: get_emulation_routine+4D↑o
                di
; NOTE! This code is buggy and hangs the card.

; 0000-1FFF - Common Area 0 (no translation)
; 2000-3FFF - Common Area 0 (00/2000 - 00/3FFF aka Main DHR)
; 4000-8FFF - Common Area 0 (no translation)
; 9000-9FFF - Bank Area (01/1000 - 01/1FFF)
; A000-BFFF - Bank Area (01/2000 - 01/3FFF aka Aux DHR)
; C000-FFFF - Common Area 1 (0A/0000 - 0A/3FFF aka VRAM)
                ld      a, #0xC9
                out0    (0x3A), a       ; MMU Common/Bank Area Register (CBAR)
                ld      a, #8
                out0    (0x39), a       ; MMU Bank Base Register (BBR)
                ld      a, #0x94
                out0    (0x38), a       ; MMU Common Base Register (CBR)
                call    access_softswitch1 ; Access the softswitch at 5/0000
                ld      a, #0xFA        ; 560x192x16
                call    set_video_mode  ; A = video mode (13 = 320x200x256, 53 = 640x480x256, etc)
                ld      a, #1
                ld      bc, #0x3C4
                out     (c), a          ; Select sequencer clocking mode register
                ld      bc, #0x3C5
                in      a, (c)
                res     5, a            ; Turn on screen
                ld      d, a
                ld      a, #1
                ld      bc, #0x3C4
                out     (c), a          ; Select sequencer clocking mode register
                ld      a, d
                ld      bc, #0x3C5
                out     (c), a
                call    set_double_hires_palette
                call    copy_double_hires_a_b_lookup_tables
                ld      a, #2
                ld      bc, #0x3C4
                out     (c), a          ; Select sequencer map mask register
                ld      a, #0xF         ; Write to all planes
                ld      bc, #0x3C5
                out     (c), a
                ld      hl, #unk_8E13   ; Source address = 00/8E13
                ld      (word_CD3), hl
                ld      a, #0
                ld      (byte_CD5), a
                ld      hl, #0          ; Destination address = 0A/0000
                ld      (word_CD6), hl
                ld      (word_CD9), hl
                ld      a, #0xA
                ld      (byte_CD8), a
                call    fill_memory_block
                call    copy_double_hires_colour_lookup_tables
                ld      a, #2
                ld      bc, #0x3C4
                out     (c), a          ; Select sequencer map mask register
                ld      a, #1
                ld      bc, #0x3C5
                out     (c), a          ; Write to plane 0
                ld      a, #0x23 ; '#'
                ld      bc, #0x3DE
                out     (c), a          ; Select Oak Extended Read Segment register
                ld      a, #1
                ld      bc, #0x3DF
                out     (c), a          ; Extended Read Segment = 1
                ld      a, #0x24 ; '$'
                ld      bc, #0x3DE
                out     (c), a          ; Select Oak Extended Write Segment register
                ld      a, #0
                ld      bc, #0x3DF
                out     (c), a          ; Extended Write Segment = 0
                ei
                jp      sub_1E01
