set_videomode_superhires:               ; DATA XREF: get_emulation_routine+15↑o
                ld      a, #0
                out0    (0x20), a       ; DMA Source Address Register Channel 0L (SAR0L)
                ld      a, #0xA0
                out0    (0x21), a       ; DMA Source Address Register Channel 0H (SAR0H)
                ld      a, #0
                out0    (0x22), a       ; DMA Source Address Register Channel 0B (SAR0B)
                ld      a, #0
                out0    (0x23), a       ; DMA Destination Address Register Channel 0L (DAR0L)
                ld      a, #0xA0
                out0    (0x24), a       ; DMA Destination Address Register Channel 0H (DAR0H)
                ld      a, #1
                out0    (0x25), a       ; DMA Destination Address Register Channel 0B (DAR0B)
                ld      a, #0
                out0    (0x26), a       ; DMA Byte Count Register Channel 0L (BCR0L)
                ld      a, #0x20 ; ' '
                out0    (0x27), a       ; DMA Byte Count Register Channel 0H (BCR0H)
                in0     a, (0x31)
                or      #2
                and     #0xC3
                ld      a, a
                out0    (0x31), a
                in0     a, (0x30)
                or      #0x41 ; 'A'
                and     #0xEF
                ld      a, a
                out0    (0x30), a
                ld      a, #0xF2
                out0    (0x3A), a       ; MMU Common/Bank Area Register (CBAR)
                ld      a, #0x10
                out0    (0x39), a       ; MMU Bank Base Register (BBR)
                ld      a, #0x91
                out0    (0x38), a       ; MMU Common Base Register (CBR)
                ld      a, #5
                ld      bc, #0x3DE
                out     (c), a
                ld      a, #0
                ld      bc, #0x3DF
                out     (c), a
                call    access_softswitch1 ; Access the softswitch at 5/0000
                ld      a, #0
                out0    (0xAA), a
                ld      a, #0xFE        ; 640x200
                call    set_video_mode  ; A = video mode (13 = 320x200x256, 53 = 640x480x256, etc)
                ld      a, #0
                out0    (0x32), a
                ld      a, #0x22 ; '"'  ; Oak Feature Select Register
                ld      bc, #0x3DE
                out     (c), a
                ld      a, #0x1C        ; Enable 64-bit graphics latch / read+write cache
                ld      bc, #0x3DF
                out     (c), a
                call    sub_AD95
                call    sub_AEB2
                ld      a, #0x23 ; '#'
                ld      bc, #0x3DE
                out     (c), a
                ld      a, #0xC         ; Set Oak Extended Read Segment Register = 0x0C
                ld      bc, #0x3DF
                out     (c), a
                ld      a, #4           ; Select Sequencer Memory Mode
                ld      bc, #0x3C4
                out     (c), a
                ld      a, #0xA         ; Memory Mode = Chain Four + Extended memory
                ld      bc, #0x3C5
                out     (c), a
                ld      a, #0x22 ; '"'  ; Oak Feature Select Register
                ld      bc, #0x3DE
                out     (c), a
                ld      a, #0x38 ; '8'  ; Enable 64-bit graphics latch / read+write cache / swap latch
                ld      bc, #0x3DF
                out     (c), a
                ld      a, #0x30 ; '0'  ; Select Color Expansion Control Register
                ld      bc, #0x3DE
                out     (c), a
                ld      a, #8           ; Turn on pixel mask
                ld      bc, #0x3DF
                out     (c), a
                ld      a, #0x34 ; '4'  ; Select Pixel Mask Register
                ld      bc, #0x3DE
                out     (c), a
                ld      a, #0xFF
                ld      bc, #0x3DF
                out     (c), a          ; Pixel mask = FF
                ld      a, #5
                ld      bc, #0x3CE      ; Select Graphics Controller Mode Register
                out     (c), a
                ld      a, #0x51 ; 'Q'  ; Mode = Mode 13 Shift Register + Odd/Even + Write Mode 1
                ld      bc, #0x3CF
                out     (c), a
                ld      a, #0xFF
                ld      (byte_ABA1), a
                ld      (byte_ABA2), a
                call    render_superhires
                call    set_superhires_palette
                ld      a, #1
                ld      bc, #0x3C4
                out     (c), a
                ld      bc, #0x3C5
                in      a, (c)
                res     5, a
                ld      d, a
                ld      a, #1
                ld      bc, #0x3C4
                out     (c), a
                ld      a, d
                ld      bc, #0x3C5
                out     (c), a
                ld      a, #0
                ld      (byte_A006), a
                ld      hl, #0x9E00
                ld      (word_A001), hl
                ld      hl, #0xBB00
                ld      (word_A003), hl
                ld      hl, #0x9D00
                ld      de, #0xBD00
                ld      bc, #0x100
                ldir
                ld      a, #0
                out0    (0x39), a       ; MMU Bank Base Register (BBR)
                ld      a, #0
                out0    (0x38), a       ; MMU Common Base Register (CBR)
                jp      sub_1E01
; End of function set_videomode_superhires


