emulate_superhires:                     ; CODE XREF: emulate_superhires+1E↓j
                                        ; DATA XREF: get_emulation_routine+18↑o
                ld      a, #0xF2
                out0    (0x3A), a       ; MMU Common/Bank Area Register (CBAR)
                ld      a, #0x10
                out0    (0x39), a       ; MMU Bank Base Register (BBR)
                ld      a, #0x91
                out0    (0x38), a       ; MMU Common Base Register (CBR)
                call    render_superhires
                ld      a, (emul_flag)  ; 00 = emulating Apple II video modes, 01 = disable emulation
                cp      #1
                jr      Z, loc_A14F
                ld      a, (byte_1A3B)
                cp      #0
                jr      Z, emulate_superhires

